J('éclats: achat réel chez Galet (x6)',"""(async()=>{const L=__lumen;L.st.player.ecus=2000;const rows=[];L.G.screens.shop('galet',false);await T.tick(200);
  const lis=[...document.querySelectorAll('#screen .shop-list li')].map(li=>li.textContent.slice(0,40));
  const btn=[...document.querySelectorAll('#screen [data-buy]')].find(b=>b.closest('li').textContent.includes('Éclat'));let n=0;while(btn&&n<8&&!btn.disabled){const e0=L.st.player.ecus;btn.click();await T.tick(100);if(L.st.player.ecus===e0)break;n++;}
  L.G.screens.close();return 'achats='+n+' eclats='+(L.st.inv.eclat_verre||0)+' '+T.q('q_phare_verre')+' '+JSON.stringify(lis)})()""")
